import{_ as i,l as n,o as a,c as s,v as t,p as l,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"幂等键","description":"","frontmatter":{"title":"幂等键","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/idempotency-keys.md","filePath":"cs/idempotency-keys.md","lastUpdated":1789023840000}'),E={name:"cs/idempotency-keys.md"};function h(A,e,m,_,T,B){const r=n("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="幂等键" tabindex="-1">幂等键 <a class="header-anchor" href="#幂等键" aria-label="Permalink to &quot;幂等键&quot;">​</a></h1><div class="epigraph"><p>客户端生成一次请求身份，服务器把副作用与该身份绑在同一持久记录上。重试不再加效果，只返回第一次的结果。</p><footer>—— 据 Birrell–Nelson 的调用 ID；Stripe 等支付 API 的 Idempotency-Key 实践；Lamport 对重复请求的讨论整理</footer></div><p>上一课<a href="/cs/delivery-semantics">投递</a>把重复当成常态。缺口是<strong>应用层去重</strong>：不能指望队列恰好一次。本课钉幂等键的存储与生命周期，不重写 ack 点。后课 Saga 处理「一串步骤」里中间失败，不是单请求重复。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>键：客户端提供的 UUID 或 <code>(user, nonce)</code>。服务器表：<code>key → 结果或进行中</code>。相同键第二次来：若已完成则回放结果；若进行中则等待或冲突。缺口：表与副作用必须原子。先做事再记账，崩了会做两遍；先记账再做事，崩了要能恢复成同一结果。</p><p>过期：表不能无限。过期后同一键变成新请求——必须让键空间在业务上不重用，或过期长于一切重试窗口。</p><p><span class="marginnote">HTTP 的 <code>PUT</code> 幂等是方法性质；<code>POST</code> + Idempotency-Key 是协议补丁。二者都要服务器状态。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生成：客户端在第一次尝试前生成，重试沿用，不要每次重试 new UUID。作用域：按租户加键，防碰撞。存储：与业务行同库事务，或 RSM 日志一条命令。</p>',9)),(a(),l(p,null,{default:o(()=>[c(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E9%94%AE%22%5D%20--%3E%20T%5B%22%E5%8E%BB%E9%87%8D%E8%A1%A8%22%5D%0A%20%20T%20--%3E%20NEW%5B%22%E9%A6%96%E6%AC%A1%3A%20%E6%89%A7%E8%A1%8C%E5%B9%B6%E8%AE%B0%E5%BD%95%22%5D%0A%20%20T%20--%3E%20OLD%5B%22%E5%86%8D%E6%AC%A1%3A%20%E5%9B%9E%E6%94%BE%E7%BB%93%E6%9E%9C%22%5D%0A%20%20NEW%20--%3E%20TX%5B%22%E4%B8%8E%E5%89%AF%E4%BD%9C%E7%94%A8%E5%90%8C%E4%BA%8B%E5%8A%A1%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>只对写。只读天然幂等，不必键——除非读有副作用（计数器）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>进行中状态：两个重试并发，要用表上的条件插入当锁，输家等或拿同一结果。否则仍双写。这把<a href="/cs/distributed-lock-fencing">分布式锁</a>缩小到一行键上，fencing 可以是该行版本。</p><p>与 CRDT：幂等键是「同一命令不执行两遍」，CRDT 是「两遍执行结果相同」。计数器 +1 不是幂等，除非 +1 带命令 id。选错代数就会在重试下多加。</p><p>本课不把区块链 nonce 当 HTTP 幂等键课。也不写支付合规。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不设计键的密码学强度全文。不引入 Saga 的补偿键空间。后课默认：至少一次 RPC/消息必须配幂等键或半格操作。Saga 下一课把多步骤的部分执行当对象，单键盖不住跨服务。</p><p>键的生命周期 ≥ 重试窗口。短了等于没键。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>幂等键把重复请求映射到同一持久效果。</li><li>记账与副作用要原子；并发重试要占行。</li><li>键过期不得短于重试；客户端不得每次换键。</li><li>出处：Birrell and Nelson 调用 ID；实践中的 Idempotency-Key。</li></ul>',10))])}const D=i(E,[["render",h]]);export{f as __pageData,D as default};
